    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        res, cur = [], []

        def dfs(i, remain):
            if remain == 0:
                res.append(cur.copy())
                return
            if i == len(candidates) or remain < 0:
                return
            cur.append(candidates[i])  # use candidates[i] (again)
            dfs(i, remain - candidates[i])
            cur.pop()
            dfs(i + 1, remain)          # move past candidates[i] for good

        dfs(0, target)
        return res
