:::

:::details 2. Brute force: whole-grid simulation
Each minute, scan every cell and collect the fresh oranges that touch a rotten one, then rot them all at once (collecting first stops rot from spreading twice in one minute). Stop when nothing changes, then check for leftover fresh oranges.

**Java**

```java
class Solution {
    public int orangesRotting(int[][] grid) {
        int rows = grid.length, cols = grid[0].length, minutes = 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (true) {
            // one simulated minute: find every fresh orange next to a rotten one
            List<int[]> toRot = new ArrayList<>();
            for (int r = 0; r < rows; r++)
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != 1) continue;
                    for (int[] d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && grid[nr][nc] == 2) {
                            toRot.add(new int[]{r, c});
                            break;
                        }
                    }
                }
            if (toRot.isEmpty()) break;
            for (int[] cell : toRot) grid[cell[0]][cell[1]] = 2;
            minutes++;
        }
        for (int[] row : grid) for (int v : row) if (v == 1) return -1;
        return minutes;
    }
}
```

