:::

:::details 2. Multi-source BFS uphill
The same reverse search with a queue per ocean, seeded with all its border cells at once. No deep recursion on a 200 × 200 grid.

**Java**

```java
class Solution {
    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length, cols = heights[0].length;
        Deque<int[]> pq = new ArrayDeque<>(), aq = new ArrayDeque<>();
        for (int c = 0; c < cols; c++) { pq.add(new int[]{0, c}); aq.add(new int[]{rows - 1, c}); }
        for (int r = 0; r < rows; r++) { pq.add(new int[]{r, 0}); aq.add(new int[]{r, cols - 1}); }
        boolean[][] pac = reach(heights, pq), atl = reach(heights, aq);
        List<List<Integer>> res = new ArrayList<>();
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (pac[r][c] && atl[r][c]) res.add(List.of(r, c));
        return res;
    }

    private boolean[][] reach(int[][] h, Deque<int[]> q) {
        int rows = h.length, cols = h[0].length;
        boolean[][] seen = new boolean[rows][cols];
        for (int[] s : q) seen[s[0]][s[1]] = true;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            for (int[] d : dirs) {
                int nr = cell[0] + d[0], nc = cell[1] + d[1];
                if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && !seen[nr][nc]
                        && h[nr][nc] >= h[cell[0]][cell[1]]) {
                    seen[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return seen;
    }
}
```

