                    board[nr][nc] = "S"
                    q.append((nr, nc))
        for r in range(rows):
            for c in range(cols):
                board[r][c] = "O" if board[r][c] == "S" else "X"
```

**Time:** O(m·n)
**Space:** O(m·n) queue
:::

:::details 3. Union-Find with a virtual border node
Union each `O` with its right and down `O` neighbours, and union every border `O` with an extra "edge" node. Afterwards, any `O` not in the edge node's set is surrounded.

**Java**

```java
class Solution {
    private int[] parent;

    public void solve(char[][] board) {
        int rows = board.length, cols = board[0].length, edge = rows * cols; // virtual node for the border
        parent = new int[edge + 1];
        for (int i = 0; i <= edge; i++) parent[i] = i;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                if (board[r][c] != 'O') continue;
                if (r == 0 || c == 0 || r == rows - 1 || c == cols - 1) union(r * cols + c, edge);
                if (r + 1 < rows && board[r + 1][c] == 'O') union(r * cols + c, (r + 1) * cols + c);
                if (c + 1 < cols && board[r][c + 1] == 'O') union(r * cols + c, r * cols + c + 1);
            }
        int safe = find(edge);
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (board[r][c] == 'O' && find(r * cols + c) != safe) board[r][c] = 'X';
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        parent[find(a)] = find(b);
    }
}
```

