class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(numCourses)]
        for course, pre in prerequisites:
            graph[course].append(pre)
        state = [0] * numCourses  # 0 = unvisited, 1 = on path, 2 = done
        order = []

        def dfs(c):
            if state[c] == 1:
                return False  # cycle
            if state[c] == 2:
                return True
            state[c] = 1
            for p in graph[c]:
                if not dfs(p):
                    return False
            state[c] = 2
            order.append(c)  # post-order: all prerequisites are already in order
            return True

        for c in range(numCourses):
            if not dfs(c):
                return []
        return order
