            count++;
            seen[start] = true;
            Deque<Integer> q = new ArrayDeque<>(List.of(start));
            while (!q.isEmpty())
                for (int nb : graph.get(q.poll()))
                    if (!seen[nb]) {
                        seen[nb] = true;
                        q.add(nb);
                    }
        }
